import React, { useState } from 'react';
import { View, Text, ScrollView, Button } from '@tarojs/components';
import { useStore } from '../../store';
import { Booking, Service } from '../../types';
import { formatDate, formatTime, generateId } from '../../utils';
import dayjs from 'dayjs';
import './index.css';

const CoachHome: React.FC = () => {
  const {
    coachSettings,
    updateCoachSettings,
    bookings,
    updateBookingStatus,
    services,
    addService,
    updateService,
    deleteService,
  } = useStore();

  const [activeTab, setActiveTab] = useState<'bookings' | 'calendar' | 'settings'>('bookings');
  const [selectedDate, setSelectedDate] = useState(dayjs().format('YYYY-MM-DD'));
  const [newService, setNewService] = useState<Omit<Service, 'id'>>({
    name: '',
    duration: 60,
    price: 0,
    description: '',
  });

  // 处理预约状态更新
  const handleStatusUpdate = (id: string, status: Booking['status']) => {
    updateBookingStatus(id, status);
  };

  // 处理服务添加
  const handleAddService = () => {
    if (!newService.name) return;

    const service: Service = {
      id: generateId(),
      ...newService,
    };

    addService(service);
    setNewService({
      name: '',
      duration: 60,
      price: 0,
      description: '',
    });
  };

  // 处理设置更新
  const handleSettingUpdate = (key: keyof typeof coachSettings, value: any) => {
    updateCoachSettings({ [key]: value });
  };

  // 生成日期导航
  const generateDateNav = () => {
    const dates = [];
    const today = dayjs();
    
    for (let i = 0; i < 5; i++) {
      const date = today.add(i, 'day');
      dates.push({
        date: date.format('YYYY-MM-DD'),
        day: date.format('ddd'),
        dayNumber: date.date(),
        isActive: date.format('YYYY-MM-DD') === selectedDate,
      });
    }
    
    return dates;
  };

  // 处理日期选择
  const handleDateSelect = (date: string) => {
    setSelectedDate(date);
  };

  // 生成时间轴数据
  const generateTimelineData = () => {
    const timelineData = [];
    const selectedDayBookings = bookings.filter(booking => 
      dayjs(booking.startTime).format('YYYY-MM-DD') === selectedDate
    );
    
    // 添加时间段
    timelineData.push(
      { type: 'period', label: '上午' },
      { 
        type: 'booking', 
        time: '09:00',
        booking: selectedDayBookings.find(b => dayjs(b.startTime).hour() === 9),
        status: 'confirmed'
      },
      { type: 'buffer', time: '10:00', duration: 15 },
      { 
        type: 'booking', 
        time: '11:00',
        booking: selectedDayBookings.find(b => dayjs(b.startTime).hour() === 11),
        status: 'pending'
      },
      { type: 'period', label: '下午' },
      { 
        type: 'booking', 
        time: '14:00',
        booking: selectedDayBookings.find(b => dayjs(b.startTime).hour() === 14),
        status: 'confirmed',
        isGroup: true
      },
      { type: 'period', label: '晚上' },
      { type: 'period', label: '22:00' }
    );
    
    return timelineData;
  };

  return (
    <View className="coach-page">
      {/* 顶部导航 */}
      <View className="coach-header">
        <View style={{ width: '40px' }}></View>
        <Text className="coach-header-title">日程管理</Text>
        <View className="coach-header-action">
          <Text>🔔</Text>
        </View>
      </View>

      {/* 日期导航 */}
      <View className="coach-nav">
        {generateDateNav().map((date, index) => (
          <View 
            key={index}
            className={`coach-nav-item ${date.isActive ? 'active' : ''}`}
            onClick={() => handleDateSelect(date.date)}
          >
            <Text className={`coach-nav-day ${date.isActive ? 'active' : ''}`}>
              {date.day}
            </Text>
            <Text className={`coach-nav-date ${date.isActive ? 'active' : ''}`}>
              {date.dayNumber}
            </Text>
          </View>
        ))}
      </View>

      {/* 内容区域 */}
      <ScrollView className="coach-content">
        {/* 预约提醒 */}
        <View className="coach-alert">
          <View className="coach-alert-content">
            <View className="coach-alert-icon">
              <Text>⏳</Text>
            </View>
            <View className="coach-alert-text">
              <Text className="coach-alert-title">2个新预约申请</Text>
              <Text className="coach-alert-subtitle">请尽快处理今日申请</Text>
            </View>
          </View>
          <Button className="coach-alert-button">去处理</Button>
        </View>

        {/* 时间轴标题 */}
        <View className="coach-section">
          <Text className="coach-section-title">时间轴</Text>
          <Text className="coach-section-subtitle">上午 08:00 - 晚上 10:00</Text>
        </View>

        {/* 时间轴 */}
        <View className="coach-timeline">
          {generateTimelineData().map((item, index) => {
            if (item.type === 'period') {
              return (
                <View key={index} className="coach-timeline-period">
                  <Text className="coach-timeline-period-label">{item.label}</Text>
                  <View className="coach-timeline-period-dot"></View>
                </View>
              );
            }
            
            if (item.type === 'booking') {
              const booking = item.booking;
              if (booking) {
                return (
                  <View key={index} className="coach-timeline-item">
                    <View className="coach-timeline-time">
                      <Text className="coach-timeline-time-label">{item.time}</Text>
                      <View className={`coach-timeline-time-dot ${item.status === 'pending' ? 'pending' : ''}`}></View>
                    </View>
                    <View className="coach-timeline-content">
                      <View className={`coach-booking-card ${item.status}`}>
                        <View className="coach-booking-header">
                          <View>
                            <Text className="coach-booking-type">
                              {item.isGroup ? '团体课' : '网球私教课'}
                            </Text>
                            <Text className="coach-booking-title">
                              学员姓名: {booking.studentName}
                            </Text>
                          </View>
                          {item.status === 'confirmed' && (
                            <Text style={{ color: 'white', fontWeight: 'bold' }}>✓</Text>
                          )}
                        </View>
                        <View className="coach-booking-details">
                          <View className="coach-booking-detail">
                            <Text>⏰</Text>
                            <Text>{formatTime(booking.startTime)} - {formatTime(booking.endTime)}</Text>
                          </View>
                          <View className="coach-booking-detail">
                            <Text>📍</Text>
                            <Text>训练地点: 4号场</Text>
                          </View>
                        </View>
                        {item.status === 'pending' && (
                          <View className="coach-booking-actions">
                            <Button 
                              className="coach-booking-action reject"
                              onClick={() => handleStatusUpdate(booking.id, 'cancelled')}
                            >
                              ✕
                              拒绝
                            </Button>
                            <Button 
                              className="coach-booking-action approve"
                              onClick={() => handleStatusUpdate(booking.id, 'confirmed')}
                            >
                              <Text style={{ color: 'white', fontWeight: 'bold' }}>✓</Text>
                              通过
                            </Button>
                          </View>
                        )}
                      </View>
                    </View>
                  </View>
                );
              } else {
                return (
                  <View key={index} className="coach-timeline-item">
                    <View className="coach-timeline-time">
                      <Text className="coach-timeline-time-label">{item.time}</Text>
                      <View className="coach-timeline-time-dot"></View>
                    </View>
                    <View className="coach-timeline-content">
                      <Button className="coach-booking-card locked">
                        <View className="coach-booking-header">
                          <View>
                            <Text className="coach-booking-type">已锁定</Text>
                            <Text className="coach-booking-title">私人时间 · 不接受预约</Text>
                          </View>
                          <Text>🚫</Text>
                        </View>
                      </Button>
                    </View>
                  </View>
                );
              }
            }
            
            if (item.type === 'buffer') {
              return (
                <View key={index} className="coach-timeline-item">
                  <View className="coach-timeline-time">
                    <Text className="coach-timeline-time-label">{item.time}</Text>
                    <View className="coach-timeline-time-dot"></View>
                  </View>
                  <View className="coach-timeline-content">
                    <View className="coach-buffer">
                      <Text>⚡</Text>
                      休息 ({item.duration}分钟)
                    </View>
                  </View>
                </View>
              );
            }
            
            return null;
          })}
        </View>

        {/* 设置部分 */}
        {activeTab === 'settings' && (
          <View>
            {/* 课程时长设置 */}
            <View className="coach-settings-section">
              <Text className="coach-settings-section-title">课程时长</Text>
              <View className="coach-settings-card">
                <View className="coach-service-duration">
                  {services.map((service) => (
                    <View 
                      key={service.id}
                      className={`coach-service-duration-item ${service.duration === 60 ? 'active' : ''}`}
                    >
                      <Text>⏰</Text>
                      <Text>{service.duration}分钟</Text>
                    </View>
                  ))}
                  <View className="coach-service-duration-item add">
                    <Text>➕</Text>
                    <Text>添加新时长</Text>
                  </View>
                </View>
                <Text className="coach-service-duration-hint">
                  选择您可以提供给学生的课程长度。
                </Text>
              </View>
            </View>

            {/* 课间休息设置 */}
            <View className="coach-settings-section">
              <Text className="coach-settings-section-title">课间休息</Text>
              <View className="coach-settings-card">
                <View style={{ marginBottom: '8px' }}>
                  <Text style={{ fontSize: '20px', fontWeight: 'bold', color: 'var(--primary-color)' }}>
                    {coachSettings.bufferTime}分钟
                  </Text>
                  <Text style={{ fontSize: '14px', color: 'var(--text-secondary)' }}>
                    课程之间的间隔
                  </Text>
                </View>
                <View className="coach-buffer-slider">
                  <View className="coach-buffer-slider-track">
                    <View 
                      className="coach-buffer-slider-progress"
                      style={{ width: `${(coachSettings.bufferTime / 60) * 100}%` }}
                    ></View>
                    <View 
                      className="coach-buffer-slider-thumb"
                      style={{ left: `${(coachSettings.bufferTime / 60) * 100}%` }}
                    ></View>
                  </View>
                  <View className="coach-buffer-labels">
                    <Text className="coach-buffer-label">无</Text>
                    <Text className="coach-buffer-label">10分钟</Text>
                    <Text className={`coach-buffer-label ${coachSettings.bufferTime === 15 ? 'active' : ''}`}>15分钟</Text>
                    <Text className="coach-buffer-label">30分钟</Text>
                    <Text className="coach-buffer-label">45分钟</Text>
                    <Text className="coach-buffer-label">60分钟</Text>
                  </View>
                </View>
              </View>
            </View>

            {/* 预约窗口设置 */}
            <View className="coach-settings-section">
              <Text className="coach-settings-section-title">预约窗口</Text>
              <View className="coach-settings-card">
                <View className="coach-settings-item">
                  <View className="coach-settings-item-content">
                    <View className="coach-settings-item-icon">
                      <Text>⚡</Text>
                    </View>
                    <View className="coach-settings-item-text">
                      <Text className="coach-settings-item-title">最少提前预约</Text>
                      <Text className="coach-settings-item-subtitle">避免最后一分钟的预约</Text>
                    </View>
                  </View>
                  <View className="coach-settings-item-value">
                    <Text className="coach-settings-item-value-text">{coachSettings.minAdvanceHours} 小时</Text>
                    <Text>⬇</Text>
                  </View>
                </View>
                <View className="coach-settings-item">
                  <View className="coach-settings-item-content">
                    <View className="coach-settings-item-icon">
                      <Text>📅</Text>
                    </View>
                    <View className="coach-settings-item-text">
                      <Text className="coach-settings-item-title">最大预约范围</Text>
                      <Text className="coach-settings-item-subtitle">学生最远可预约的时间</Text>
                    </View>
                  </View>
                  <View className="coach-settings-item-value">
                    <Text className="coach-settings-item-value-text">{coachSettings.maxFutureDays} 天</Text>
                    <Text>⬇</Text>
                  </View>
                </View>
                <View className="coach-settings-item">
                  <View className="coach-settings-item-content">
                    <View className="coach-settings-item-icon">
                      <Text>✓</Text>
                    </View>
                    <View className="coach-settings-item-text">
                      <Text className="coach-settings-item-title">自动接受预约</Text>
                      <Text className="coach-settings-item-subtitle">无需手动确认</Text>
                    </View>
                  </View>
                  <label className="coach-toggle">
                    <input type="checkbox" className="coach-toggle-input" />
                    <View className="coach-toggle-slider"></View>
                  </label>
                </View>
              </View>
            </View>

            {/* 全局规则 */}
            <View className="coach-settings-section">
              <Text className="coach-settings-section-title">全局规则</Text>
              <View className="coach-settings-card">
                <View className="coach-toggle-container">
                  <Text className="coach-toggle-label">允许24小时内取消</Text>
                  <label className="coach-toggle">
                    <input type="checkbox" className="coach-toggle-input" />
                    <View className="coach-toggle-slider"></View>
                  </label>
                </View>
                <View className="coach-toggle-container">
                  <Text className="coach-toggle-label">每日限接5节课</Text>
                  <label className="coach-toggle">
                    <input type="checkbox" className="coach-toggle-input" defaultChecked />
                    <View className="coach-toggle-slider"></View>
                  </label>
                </View>
              </View>
            </View>
          </View>
        )}
      </ScrollView>

      {/* 浮动按钮 */}
      <View className="coach-floating-button">
        <Text style={{ fontSize: '32px' }}>🔓</Text>
      </View>

      {/* 底部导航 */}
      <View className="coach-bottom-nav">
        <View className={`coach-nav-item-bottom ${activeTab === 'calendar' ? 'active' : ''}`} onClick={() => setActiveTab('calendar')}>
          <Text className="coach-nav-item-bottom-icon">📅</Text>
          <Text className="coach-nav-item-bottom-text">日程</Text>
        </View>
        <View className={`coach-nav-item-bottom ${activeTab === 'bookings' ? 'active' : ''}`} onClick={() => setActiveTab('bookings')}>
          <Text className="coach-nav-item-bottom-icon">👥</Text>
          <Text className="coach-nav-item-bottom-text">学员</Text>
        </View>
        <View className="coach-nav-item-bottom">
          <Text className="coach-nav-item-bottom-icon">📊</Text>
          <Text className="coach-nav-item-bottom-text">统计</Text>
        </View>
        <View className={`coach-nav-item-bottom ${activeTab === 'settings' ? 'active' : ''}`} onClick={() => setActiveTab('settings')}>
          <Text className="coach-nav-item-bottom-icon">⚙️</Text>
          <Text className="coach-nav-item-bottom-text">设置</Text>
        </View>
      </View>
    </View>
  );
};

export default CoachHome;
